// Zoom on one person's sign-in (a user-managed OAuth app): every operation such a login can call, across Zoom's products.
// actions.json and events.json are generated by `bun scripts/openapi-actions.ts zoom`; events start automations by webhook
// (triggers.ts) and the daily usage report is polled (polls/zoom.ts). Which scopes the app needs is in COVERAGE.md.
import { z } from "zod";
import { MAX_FILE_SIZE } from "../../../files";
import { AppFile, AppsError } from "../../types";
import type { OwnApp } from "../index";
import { codeFlow } from "../oauth";
import { type Api, call, rest, specActions } from "../openapi";
import { events, receive, triggers, wanted, watch } from "./triggers";

// Zoom: "Invalid access token, does not contain scopes:[a, b]"
const MISSING_SCOPE = /\bscopes?\b/i;

const api: Api = {
  name: "Zoom",
  base: "https://api.zoom.us/v2",
  tokenHelp: "sign in to Zoom again from Emplio",
  // Zoom words a missing permission as an invalid token; the login is still good
  deadToken: (status, body) => status === 401 && !MISSING_SCOPE.test(String(body?.message ?? "")),
};

// a missing permission, in words the person can act on
export function explain(error: unknown): never {
  if (!(error instanceof AppsError) || !MISSING_SCOPE.test(error.message)) throw error;
  const need = error.message.match(/\[([^\]]+)\]/)?.[1];
  const what = need ? ` (it needs ${need})` : "";
  if (need?.split(",").every((s) => /:(admin|master)\s*$/.test(s))) throw new AppsError(`Zoom only lets an account admin's app do this${what}, so it isn't available on a person's own Zoom sign-in.`);
  throw new AppsError(`Zoom hasn't given Emplio permission for this${what}. Connect Zoom again to grant it.`);
}

const flow = codeFlow({ name: "Zoom", idVar: "ZOOM_CLIENT_ID", secretVar: "ZOOM_CLIENT_SECRET", authorize: "https://zoom.us/oauth/authorize", token: "https://zoom.us/oauth/token", basic: true });

const isZoom = (host: string) => host === "zoom.us" || host.endsWith(".zoom.us");

// The address comes from the model, and our login goes with it, so only Zoom's own hosts. Zoom redirects to a signed
// address on another host; fetch drops the Authorization header on that hop.
// ponytail: reads the whole file into memory, refused above MAX_FILE_SIZE; a stream to storage if long recordings are needed
async function download(input: { download_url: string; file_name?: string }, key: string) {
  const url = URL.canParse(input.download_url) ? new URL(input.download_url) : null;
  if (url?.protocol !== "https:" || !isZoom(url.hostname)) throw new AppsError("download_url must be a recording file's download_url from Zoom");
  const res = await fetch(url, { headers: { Authorization: `Bearer ${key}` }, signal: AbortSignal.timeout(300_000) });
  const type = (res.headers.get("content-type") ?? "application/octet-stream").split(";")[0]!;
  // without access Zoom answers 200 with its sign-in page
  if (!res.ok || type === "text/html") throw new AppsError(`Zoom wouldn't hand over that file (${res.status}). The recording may be gone, or this sign-in may not be allowed to download it.`);
  if (Number(res.headers.get("content-length")) > MAX_FILE_SIZE) throw new AppsError(`That recording is over ${MAX_FILE_SIZE / 1024 / 1024} MB, too big to bring over. Use its share_url instead.`);
  const named = res.headers.get("content-disposition")?.match(/filename="?([^";]+)/)?.[1];
  return new AppFile(input.file_name ?? named ?? "zoom-recording", type, new Uint8Array(await res.arrayBuffer()));
}

const actions: OwnApp["actions"] = {
  ...(await specActions(new URL("./actions.json", import.meta.url), api)),
  // the spec's request body for this one is malformed, so the generator can't read it
  quick_add_event: rest(api, "POST", "/calendars/{calId}/events/quickAdd", "Add an event to a Zoom calendar from a plain sentence, like \"Lunch with Asha tomorrow at 1pm\".", z.object({
    calId: z.string().describe("The calendar's id, usually the person's email address"),
    text: z.string().describe("The sentence describing the event"),
    sendUpdates: z.enum(["all", "externalOnly", "none"]).optional().describe("Who gets notified about the new event"),
  }), { query: ["text", "sendUpdates"] }),
  download_recording_file: {
    description: "Download one file of a cloud recording (the video, audio, transcript or chat) to the computer. Take download_url from list_all_recordings or get_meeting_recordings.",
    readOnly: true,
    input: z.object({
      download_url: z.string().describe("The file's download_url, from recording_files in list_all_recordings or get_meeting_recordings"),
      file_name: z.string().optional().describe("What to call the file, with its extension, like team-call.mp4"),
    }),
    run: download,
  },
};
for (const a of Object.values(actions)) {
  const run = a.run;
  a.run = (input, key) => run(input, key).catch(explain);
}

export const zoom: OwnApp = {
  app: "zoom",
  name: "Zoom",
  logo: "/logos/zoom.svg",
  async check(key) {
    const me = (await call(api, key, { method: "GET", path: "/users/me", query: [], headers: [] }, {})) as { display_name?: string; first_name?: string; email?: string };
    return me.display_name || me.email || me.first_name;
  },
  oauth: {
    ...flow,
    noConsentScreen: true,
    // Zoom says a dead refresh token with "invalid_request", not the usual invalid_grant
    refresh: (token) =>
      flow.refresh!(token).catch((error) => {
        throw error instanceof AppsError && /invalid|expired|not exist|not found/i.test(error.message) ? new AppsError(error.message, true) : error;
      }),
  },
  push: {
    events,
    triggers,
    appWide: true,
    start: (key) => watch(api, key),
    receive,
    wanted,
  },
  actions,
};
